look.customCSS:
/* ───── 霓虹夜 · 第一批 ───── */
[data-wk="chat"]{background:radial-gradient(circle at 0% 100%,rgba(196,40,130,.45),transparent 55%),radial-gradient(circle at 100% 0%,rgba(30,150,150,.35),transparent 50%),radial-gradient(circle at 80% 55%,rgba(255,95,174,.18),transparent 45%),url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc0OCcgaGVpZ2h0PScyNCcgdmlld0JveD0nMCAwIDQ4IDI0Jz48cGF0aCBkPSdNMCAuNSBINDggTTAgMTIuNSBINDggTTI0IDAgVjEyIE0uNSAxMiBWMjQgTTQ3LjUgMTIgVjI0JyBzdHJva2U9J3JnYmEoMjU1LDI1NSwyNTUsLjAzNSknIHN0cm9rZS13aWR0aD0nMScgZmlsbD0nbm9uZScvPjwvc3ZnPg==") 0 0/48px 24px,#0E0B19 !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：半透明夜色，底边一根洋红灯管 */
[data-wk="chathead"]{background:rgba(14,11,25,.82) !important;border-bottom:1.5px solid #FF5FAE !important;box-shadow:0 1px 10px rgba(255,95,174,.5) !important}
[data-wk="headink"],[data-wk="headink"] *{color:#F4F0FF !important}
[data-wk="headname"] [data-wk="headink"]{text-shadow:0 0 6px rgba(255,255,255,.5) !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#9C93B8 !important}
[data-wk="chatback"] svg{stroke:#F4F0FF !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important;filter:drop-shadow(0 0 4px #FF5FAE) !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:6px !important;filter:drop-shadow(0 0 4px #43EEDD) !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
/* 顶栏双头像：两个灯圈挨着，一青一粉，中间一颗小爱心灯 */
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-10px !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img{border-radius:50% !important;box-shadow:0 0 0 2px #FF5FAE,0 0 2px #FF5FAE,0 0 8px #FF5FAE,0 0 18px rgba(255,95,174,.55) !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-8px !important;bottom:-4px !important;width:14px !important;height:14px !important;z-index:3 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 3px #F6C764) !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}

/* 头像：圆的灯圈——他的青、我的粉 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="chathead"] img{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]),[data-wk="chathead"] [data-wk="avatar"]{box-shadow:0 0 0 2px #43EEDD,0 0 2px #43EEDD,0 0 8px #43EEDD,0 0 18px rgba(67,238,221,.5) !important}
[data-wk="msg"][data-me="1"] button[data-wk="avatar"],[data-wk="msg"][data-me="1"] span[data-wk="avatar"],[data-wk="cardrow"][data-me="1"] button[data-wk="avatar"],[data-wk="cardrow"][data-me="1"] span[data-wk="avatar"],[data-wk="msg"][data-me="1"] [data-wk="avatar"],[data-wk="cardrow"][data-me="1"] [data-wk="avatar"]{box-shadow:0 0 0 2px #FF5FAE,0 0 2px #FF5FAE,0 0 8px #FF5FAE,0 0 18px rgba(255,95,174,.55) !important}

/* 气泡：一根霓虹灯管——圆角描边、里外都亮；左下多绕出一截灯管（我的左下拐一个弯，他的左边多一道竖管） */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;background:rgba(14,11,25,.55) !important;border-radius:18px !important;color:#F4F0FF !important;padding:11px 20px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{border:2px solid #FF5FAE !important;box-shadow:0 0 6px #FF5FAE,inset 0 0 6px #FF5FAE,0 0 18px rgba(255,95,174,.45) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{border:2px solid #43EEDD !important;box-shadow:0 0 6px #43EEDD,inset 0 0 6px #43EEDD,0 0 18px rgba(67,238,221,.4) !important}
/* 照参考：灯管顶上正中一个小黑灯座卡扣；右下角灯管断开一小截，像真的弯管接头 */
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;left:calc(50% - 8px) !important;top:-4px !important;right:auto !important;bottom:auto !important;width:16px !important;height:6px !important;border-radius:2px !important;background:#1A1626 !important;border:1px solid #4A4560 !important;box-shadow:none !important;transform:none !important;pointer-events:none !important;z-index:2 !important}
[data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;right:12px !important;bottom:-4px !important;left:auto !important;top:auto !important;width:12px !important;height:6px !important;border:none !important;border-radius:0 !important;background:#140E20 !important;box-shadow:0 0 4px #140E20 !important;transform:none !important;pointer-events:none !important;z-index:2 !important}

/* 时间：一行暖金灯字，不带底 */
[data-wk="time"] > span{background:rgba(14,11,25,.6) !important;border:2px solid #F6C764 !important;border-radius:14px !important;padding:4px 22px !important;box-shadow:0 0 6px #F6C764,inset 0 0 6px rgba(246,199,100,.6) !important;color:#F6C764 !important;font-family:ui-monospace,Menlo,monospace !important;letter-spacing:.18em !important;font-size:12px !important;text-shadow:0 0 6px rgba(246,199,100,.8) !important}
/* 已读：小字，前面（我的在后面）一颗亮点 */
[data-wk="meta"]{color:#9C93B8 !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:6px !important;height:6px !important;border-radius:50% !important;background:#43EEDD !important;box-shadow:0 0 6px #43EEDD !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]::before{background:#FF5FAE !important;box-shadow:0 0 6px #FF5FAE !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#9C93B8 !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:rgba(14,11,25,.55) !important;border:2px solid #43EEDD !important;border-radius:18px !important;box-shadow:0 0 6px #43EEDD,inset 0 0 6px #43EEDD !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#43EEDD !important;box-shadow:0 0 4px #43EEDD !important}

/* 动描：不是灯管——像橱窗里一行暗下来的字幕：上下各一道渐隐的金线，淡紫斜体 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{display:block !important;background:linear-gradient(90deg,transparent,rgba(246,199,100,.7),transparent) top/100% 1px no-repeat,linear-gradient(90deg,transparent,rgba(246,199,100,.7),transparent) bottom/100% 1px no-repeat,rgba(246,199,100,.05) !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#CFC3EE !important;opacity:1 !important;font-style:italic !important;font-size:13px !important;line-height:1.8 !important;padding:8px 18px !important;text-align:center !important}
/* 系统提示：一行等宽小字，两边一颗灭着的小灯 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#9C93B8 !important;font-family:ui-monospace,Menlo,monospace !important;font-size:11px !important;font-style:normal !important;letter-spacing:.08em !important}
[data-wk="sysnotetext"]::before{content:"◦ " !important;color:#43EEDD !important}
[data-wk="sysnotetext"]::after{content:none !important}

/* 底栏：夜色，顶边一根青色灯管；左加号、发送是一道洋红闪电，右回复是青色灯管对话框里一颗心；按键都不包框，换成配套灯管图案 */
[data-wk="composer"]{background:rgba(14,11,25,.88) !important;border-top:1.5px solid #43EEDD !important;box-shadow:0 -1px 10px rgba(67,238,221,.35) !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#17132A !important;border:1.5px solid rgba(244,240,255,.25) !important;border-radius:18px !important;color:#F4F0FF !important}
[data-wk="chatinput"]::placeholder{color:#9C93B8 !important}
[data-wk="chatplus"]{width:32px !important;min-width:32px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 4px #43EEDD) !important}
[data-wk="send"]{width:40px !important;min-width:40px !important;height:36px !important;border:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:none !important;opacity:1 !important;filter:drop-shadow(0 0 5px #FF5FAE) !important}
[data-wk="chatreply"]{width:48px !important;min-width:48px !important;height:34px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 5px #43EEDD) !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
/* 顶栏：双头像挤一点、两颗都锁成正圆；名字那块不许被压扁 */
[data-wk="chathead"] [data-wk="headme"]{margin-left:-16px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:34px !important;height:34px !important;min-width:34px !important;flex-shrink:0 !important;aspect-ratio:1 !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:64px !important}
[data-wk="chathead"] [data-wk="headname"] > div:last-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}
[data-wk="chathead"] [data-wk="sameroom"],[data-wk="chathead"] [data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="chatmore"]{margin-left:2px !important}

/* ───── 霓虹夜 · 第二批：卡片（形状不动；每张是一块挂墙上的灯牌——深色底、灯管描边、顶上一个灯座卡扣） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:rgba(14,11,25,.78) !important;border:2px solid #43EEDD !important;border-radius:14px !important;box-shadow:0 0 6px #43EEDD,inset 0 0 6px #43EEDD,0 0 16px rgba(67,238,221,.35) !important;color:#F4F0FF !important}
[data-wk="transfercard"]::before,[data-wk="photocard"]::before,[data-wk="namecard"]::before,[data-part="offlog"]::before,[data-wk="wxcard"]::before{content:"" !important;position:absolute !important;left:calc(50% - 9px) !important;top:-5px !important;width:18px !important;height:7px !important;border-radius:2px !important;background:#1A1626 !important;border:1px solid #4A4560 !important;z-index:3 !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *{color:#F4F0FF !important;border-color:rgba(244,240,255,.15) !important}
/* 转账：金色灯管，金额是会亮的金字；收下以后右上亮一块青色「已收」小灯牌 */
[data-wk="transfercard"]{border-color:#F6C764 !important;box-shadow:0 0 6px #F6C764,inset 0 0 6px #F6C764,0 0 16px rgba(246,199,100,.35) !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#F6C764 !important;text-shadow:0 0 8px rgba(246,199,100,.8) !important}
[data-wk="transferrule"]{border:none !important;height:1.5px !important;background:#F6C764 !important;box-shadow:0 0 6px #F6C764 !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:transparent !important;border-top:1px solid rgba(246,199,100,.3) !important}
[data-wk="transferbtn"]{border-radius:14px !important;background:transparent !important}
[data-wk="transferbtn"][data-part="take"]{border:2px solid #F6C764 !important;color:#F6C764 !important;box-shadow:0 0 6px #F6C764 !important}
[data-wk="transferbtn"][data-part="back"]{border:1.5px solid rgba(244,240,255,.3) !important;color:#9C93B8 !important}
[data-wk="transferseal"]{background:transparent !important;border:2px solid #43EEDD !important;border-radius:6px !important;color:#43EEDD !important;box-shadow:0 0 6px #43EEDD !important;text-shadow:0 0 6px #43EEDD !important}
[data-wk="transferseal"] *{color:#43EEDD !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-6deg) !important}
[data-wk="transfercard"][data-status="returned"]{border-color:rgba(244,240,255,.25) !important;box-shadow:none !important;opacity:.6 !important}
/* 红包：不是信封——一块洋红礼物灯牌，左上一只金色灯管蝴蝶结；领完灯灭（变暗不发光） */
[data-wk="rpcard"]{background:radial-gradient(circle at 20% 0%,rgba(255,95,174,.25),transparent 60%),rgba(14,11,25,.8) !important;border-color:#FF5FAE !important;box-shadow:0 0 6px #FF5FAE,inset 0 0 6px #FF5FAE,0 0 18px rgba(255,95,174,.45) !important;padding-left:46px !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:8px !important;top:-10px !important;width:34px !important;height:34px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 4px #F6C764) !important;z-index:3 !important}
[data-wk="rpcard"] *{color:#F4F0FF !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{border-color:rgba(255,95,174,.35) !important;box-shadow:none !important;opacity:.6 !important}
[data-wk="rpcard"][data-status="done"]::before{filter:none !important;opacity:.4 !important}
[data-wk="rpenvelope"]{background:radial-gradient(circle at 50% 0%,rgba(255,95,174,.3),transparent 60%),#0E0B19 !important;border:2px solid #FF5FAE !important;border-radius:18px !important;box-shadow:0 0 6px #FF5FAE,inset 0 0 6px #FF5FAE,0 0 30px rgba(255,95,174,.45) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#F4F0FF !important}
[data-wk="rpopenbtn"]{background:transparent !important;border:2px solid #F6C764 !important;box-shadow:0 0 6px #F6C764,inset 0 0 6px #F6C764,0 0 14px #F6C764 !important}
[data-wk="rpopenbtn"] *{color:#F6C764 !important}
[data-wk="rpamount"]{color:#F6C764 !important;text-shadow:0 0 10px #F6C764 !important}
/* 照片：青色灯框里一块暗屏；语音：小灯管条，波形是一根根亮柱 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:8px !important;background:#120F20 !important;border:1px solid rgba(67,238,221,.3) !important}
[data-wk="photoface"] *,[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#F4F0FF !important}
[data-wk="photoface"] svg{stroke:#43EEDD !important}
[data-wk="voice"][data-me]{background:rgba(14,11,25,.6) !important;border:2px solid #43EEDD !important;border-radius:18px !important;box-shadow:0 0 6px #43EEDD,inset 0 0 6px #43EEDD !important}
[data-wk="voice"][data-me="1"]{border-color:#FF5FAE !important;box-shadow:0 0 6px #FF5FAE,inset 0 0 6px #FF5FAE !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#F4F0FF !important}
[data-wk="voicewave"] span{background:#43EEDD !important;box-shadow:0 0 4px #43EEDD !important}
[data-wk="voice"][data-me="1"] [data-wk="voicewave"] span{background:#FF5FAE !important;box-shadow:0 0 4px #FF5FAE !important}
/* 天气、位置、名片 */
[data-wk="wxcardsky"]{background:radial-gradient(circle at 80% 30%,rgba(67,238,221,.18),transparent 60%),transparent !important}
[data-wk="wxcardsky"] *{color:#F4F0FF !important}
[data-wk="wxcardsky"] svg{stroke:#43EEDD !important;filter:drop-shadow(0 0 4px #43EEDD) !important}
[data-wk="wxcardsky"] > div:first-child{background:radial-gradient(circle,rgba(255,95,174,.35),rgba(255,95,174,0) 70%) !important}
[data-wk="wxcardsky"] span[style*="999"],[data-wk="wxcardrain"]{background:transparent !important;border:1.5px solid #43EEDD !important;box-shadow:0 0 6px rgba(67,238,221,.6) !important;color:#F4F0FF !important}
[data-wk="wxcardsay"]{background:transparent !important;color:#F4F0FF !important;border-top:1px solid rgba(67,238,221,.3) !important}
[data-wk="wxcardsay"] *{color:#F4F0FF !important}
[data-wk="geopin"]{background:#FF5FAE !important;box-shadow:0 0 10px #FF5FAE !important}
[data-wk="geopinstem"]{background:#FF5FAE !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2px #43EEDD,0 0 2px #43EEDD,0 0 8px #43EEDD,0 0 18px rgba(67,238,221,.5) !important}
/* 拍一拍、通话结束：一行小灯字，两边各一截短灯管 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:transparent !important;border:none !important;color:#F4F0FF !important;padding:2px 26px !important;font-size:12px !important;text-shadow:0 0 6px #FF5FAE !important;background:linear-gradient(#FF5FAE,#FF5FAE) left center/16px 2px no-repeat,linear-gradient(#FF5FAE,#FF5FAE) right center/16px 2px no-repeat !important}
[data-wk="note"][data-part="call"] svg{stroke:#FF5FAE !important}
[data-wk="note"][data-part="callsum"]{color:#9C93B8 !important}
/* 线下小结 */
[data-wk="offlogtitle"]{font-family:ui-monospace,Menlo,monospace !important;letter-spacing:.2em !important;color:#43EEDD !important;text-shadow:0 0 6px #43EEDD !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#FF5FAE !important}
[data-wk="offlogtranscript"]{border-top:1px solid rgba(67,238,221,.3) !important}
/* 加号面板：一格格小灯牌，粉青交替 */
[data-wk="chatpanel"]{background:rgba(14,11,25,.92) !important;border-top:1.5px solid #43EEDD !important}
[data-wk="chattoolicon"]{background:transparent !important;border:2px solid #43EEDD !important;border-radius:14px !important;box-shadow:0 0 6px #43EEDD,inset 0 0 6px #43EEDD !important}
[data-wk="chattool"]:nth-child(odd) [data-wk="chattoolicon"]{border-color:#FF5FAE !important;box-shadow:0 0 6px #FF5FAE,inset 0 0 6px #FF5FAE !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#F4F0FF !important;color:#F4F0FF !important}
[data-wk="chattoollabel"]{color:#9C93B8 !important}
/* 引用三处：左边一根青色短灯管 */
[data-wk="quotedraft"]{background:rgba(14,11,25,.9) !important;border-top:none !important}
[data-wk="quote"]{background:rgba(23,19,42,.85) !important;color:#F4F0FF !important;border:none !important;border-left:3px solid #43EEDD !important;border-radius:4px !important;box-shadow:-2px 0 6px -2px #43EEDD !important;opacity:1 !important}
[data-wk="quote"][data-me="1"]{border-left-color:#FF5FAE !important;box-shadow:-2px 0 6px -2px #FF5FAE !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#43EEDD !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid currentColor !important;padding-left:8px !important;opacity:.7 !important}
/* 线下：提示键是同一颗四角星，照片键是一台粉色灯管相机 */
